-- Dungeon-Datenbank ns.DungeonDB: Quests, NPCs und Boss-Beute der klassischen Dungeons und Schlachtzüge und der
-- Forever-eigenen Instanzen. Karten-ID = Instanz-Karten-ID (wie ns.InstanceData).
-- Einmalig importiert am 2026-11-14 (WTFPL-Quellen), seitdem von Hand gepflegt; siehe sources.md.
-- ns.DungeonDB = {
--   quests      = { [Karten-ID] = { questID, ... } }   Quests mit Ziel, Abgabe oder Zonen-Sortierung in der Instanz,
--   questInfo   = { [questID] = { Questlevel, Mindestlevel, Fraktion ("A"/"H", nil = beide), Klassenmaske (0 = alle,
--                 Bit 2^(classID-1)), Geber-Art ("n" NPC, "o" Objekt, "i" Item, nil = unbekannt), Geber-ID, uiMapID,
--                 x, y (0-1, nil wenn unbekannt oder in einer Instanz; Item-Geber am Ort ihrer Drop-Quelle),
--                 pre = { alle diese Vorquests }, preAny = { eine davon }, excl = { schließen sie aus },
--                 giverH = { Geber-Art, Geber-ID, uiMapID, x, y } (abweichender Horde-Geber),
--                 name = Questname (enUS, Rückfall für ungecachte Titel) } }   Instanz- und Kettenquests,
--   questChains = { [questID] = { Karten-ID, Ziel-questID, Stufe, Gesamt } }   Vorquest-Kette (Stufe 1 = Anfang,
--                 Gesamt = Stufe der Instanz-Quest; Alternativen auf derselben Stufe; bei mehreren Zielen die nächste),
--   questChainAlt = { [questID] = { { Karten-ID, Ziel-questID, Stufe, Gesamt }, ... } }   weitere Instanzen, zu denen derselbe
--                 Kettenschritt führt (questChains nennt die nächste), nur Schritte ohne Eintrag in der Instanz selbst,
--   givers      = { npc = { [npcID] = { questID, ... } }, object = { ... }, item = { ... } },
--   objectNames = { [objectID] = Name }   Objekt-Geber, nur englisch,
--   npcs        = { [Karten-ID] = { [npcID] = { MinLevel, MaxLevel, Rang } } }   Rang: 0 normal, 1 Elite, 2 Rar-Elite,
--                 3 Boss, 4 Rar; Bosse aus boss_npcs.lua immer 3,
--   objectives  = { [questID] = { npcs = { npcID, ... }, items = { [itemID] = { npcs = { ... }, objects = { ... } } },
--                 objects = { objectID, ... } } }   Questziele: zu tötende NPCs, zu sammelnde Items mit ihren Quellen
--                 (droppende NPCs, Container-/Objekt-IDs), zu benutzende Objekte; leere Teile fehlen, Quests ohne
--                 Zieldaten (Gespräch, Lieferung, Forever-eigene Quests) haben keinen Eintrag,
--   loot        = { [npcID] = { { itemID, Qualität, Chance, unbestätigt }, ... } }   nur rar (3), episch (4),
--                 legendär (5), keine vollständigen Beutetabellen; Qualität aus ItemSparse (Forever-Items ohne Eintrag: 3);
--                 Chance in Prozent oder nil; viertes Feld 1 = für Forever unbestätigt (nur Classic-Daten);
--                 Forever-eigene Item-IDs (ab 250000) kennt Era nicht, sie fallen dort zur Laufzeit weg,
-- }
local _, ns = ...
-- Nur Classic Era und Forever (klassische Instanzen, Forever-Questdaten); sonst keinen Speicher belegen.
local flavor = ns.Client.Flavor()
if flavor ~= "forever" and flavor ~= "classic_era" then return end

